const sprite=(item,size='')=>{const asset=item.asset||'sprites',rect=frameRect(asset,item.cell);if(item.cat==='Accessories'){rect[1]+=rect[3]*.46;rect[3]*=.54;}return `<svg class="sprite tier-${item.tier||0}" role="img" aria-label="${esc(item.name||'Game artwork')}" viewBox="${rect.join(' ')}" style="background:none;overflow:hidden;filter:hue-rotate(${item.cat==='Laptop'||item.cat==='Accessories'?0:item.hue||0}deg) ${item.tier===3?'drop-shadow(0 0 12px #ffd25e)':item.tier===2?'drop-shadow(0 0 7px #94e7ff)':''};${size}"><image href="/${asset}.png" width="1254" height="1254"/></svg>`};
