const music={track:null,step:0,next:0,timer:null,nodes:new Set()};
function ensureAudio(){audio ||= new AudioContext();audio.resume();if(!musicGain){musicGain=audio.createGain();musicGain.gain.value=.055;musicGain.connect(audio.destination);noiseBuffer=audio.createBuffer(1,Math.ceil(audio.sampleRate*.09),audio.sampleRate);const d=noiseBuffer.getChannelData(0);for(let i=0;i<d.length;i++)d[i]=Math.random()*2-1;}return audio}
function musicTone(midi,at,duration,volume,type){if(midi==null||!musicGain)return;const o=audio.createOscillator(),g=audio.createGain(),f=440*Math.pow(2,(midi-69)/12);o.type=type;o.frequency.setValueAtTime(f,at);g.gain.setValueAtTime(.0001,at);g.gain.exponentialRampToValueAtTime(volume,at+.012);g.gain.exponentialRampToValueAtTime(.0001,at+duration);o.connect(g).connect(musicGain);music.nodes.add(o);o.onended=()=>music.nodes.delete(o);o.start(at);o.stop(at+duration+.02)}
function musicDrum(at,kind){if(!musicGain)return;if(kind==='hat'){const n=audio.createBufferSource(),f=audio.createBiquadFilter(),g=audio.createGain();n.buffer=noiseBuffer;f.type='highpass';f.frequency.value=5500;g.gain.setValueAtTime(.11,at);g.gain.exponentialRampToValueAtTime(.0001,at+.055);n.connect(f).connect(g).connect(musicGain);music.nodes.add(n);n.onended=()=>music.nodes.delete(n);n.start(at);n.stop(at+.065);return}const o=audio.createOscillator(),g=audio.createGain();o.type='sine';o.frequency.setValueAtTime(kind==='kick'?125:210,at);o.frequency.exponentialRampToValueAtTime(kind==='kick'?42:95,at+.11);g.gain.setValueAtTime(kind==='kick'?.35:.16,at);g.gain.exponentialRampToValueAtTime(.0001,at+.13);o.connect(g).connect(musicGain);music.nodes.add(o);o.onended=()=>music.nodes.delete(o);o.start(at);o.stop(at+.14)}
function scheduleMusic(){if(!audio||muted||!music.track||document.hidden)return;const cfg=musicTracks[music.track],beat=60/cfg.bpm/4;while(music.next<audio.currentTime+.16){const s=music.step,at=music.next;musicTone(cfg.lead[s],at,beat*.82,.16,cfg.wave);if(cfg.bass[s]!=null)musicTone(cfg.bass[s],at,beat*3.2,.2,'sine');if(s%4===0)musicDrum(at,'kick');else if(s%4===2)musicDrum(at,'snare');if(s%2===1)musicDrum(at,'hat');music.step=(s+1)%16;music.next+=beat}}
function stopMusic(){clearInterval(music.timer);music.timer=null;for(const n of music.nodes)try{n.stop()}catch{}music.nodes.clear();music.track=null}
function startMusic(track){if(muted||document.hidden||!musicTracks[track])return;try{ensureAudio();if(music.track===track)return;stopMusic();music.track=track;music.step=0;music.next=audio.currentTime+.04;musicGain.gain.cancelScheduledValues(audio.currentTime);musicGain.gain.setValueAtTime(.0001,audio.currentTime);musicGain.gain.exponentialRampToValueAtTime(.055,audio.currentTime+.35);scheduleMusic();music.timer=setInterval(scheduleMusic,45)}catch{}}
function wantedMusic(){return activeView==='game'&&game?`level${game.level}`:'home'}
function syncMusic(){if(!muted)startMusic(wantedMusic())}
function sound(type){if(muted)return;try{ensureAudio();const t=audio.currentTime;
 if(type==='shot'){const duration=.65,buffer=audio.createBuffer(1,Math.ceil(audio.sampleRate*duration),audio.sampleRate),wave=buffer.getChannelData(0);for(let i=0;i<wave.length;i++){const s=i/audio.sampleRate;wave[i]=(Math.random()*2-1)*Math.exp(-s*8);}const burst=audio.createBufferSource(),filter=audio.createBiquadFilter(),gain=audio.createGain();burst.buffer=buffer;filter.type='lowpass';filter.frequency.setValueAtTime(3500,t);filter.frequency.exponentialRampToValueAtTime(120,t+.55);gain.gain.value=.42;burst.connect(filter).connect(gain).connect(audio.destination);burst.start(t);const thump=audio.createOscillator(),envelope=audio.createGain();thump.frequency.setValueAtTime(135,t);thump.frequency.exponentialRampToValueAtTime(35,t+.35);envelope.gain.setValueAtTime(.32,t);envelope.gain.exponentialRampToValueAtTime(.001,t+.55);thump.connect(envelope).connect(audio.destination);thump.start(t);thump.stop(t+.6);return;}
 if(type==='boom'||type==='drum'){const dur=type==='boom'?1.1:.1,buf=audio.createBuffer(1,audio.sampleRate*dur,audio.sampleRate),d=buf.getChannelData(0);for(let i=0;i<d.length;i++)d[i]=(Math.random()*2-1)*Math.pow(1-i/d.length,2);const n=audio.createBufferSource(),filter=audio.createBiquadFilter(),g=audio.createGain();filter.type='lowpass';filter.frequency.value=type==='boom'?900:2500;g.gain.value=type==='boom'?.45:.1;n.buffer=buf;n.connect(filter).connect(g).connect(audio.destination);n.start();}
 const o=audio.createOscillator(),g=audio.createGain();o.connect(g).connect(audio.destination);o.frequency.setValueAtTime(type==='boom'?110:type==='shot'?200:type==='good'?650:type==='urgent'?850:450,t);if(type==='boom'||type==='shot')o.frequency.exponentialRampToValueAtTime(30,t+.3);g.gain.setValueAtTime(type==='urgent'?.18:.08,t);g.gain.exponentialRampToValueAtTime(.001,t+.3);o.start();o.stop(t+.31);
 }catch{}}
