function feedback(text){$('#feedback').textContent=text}
function renderWords(){if(!game)return;const g=game;$('#slots').innerHTML=g.answer.map((_,i)=>`<button class="slot ${g.selected[i]?'filled':''}" data-slot="${i}" aria-label="${g.selected[i]?'Remove '+esc(g.selected[i].word):'Empty slot '+(i+1)}">${g.selected[i]?esc(g.selected[i].word):'·'}</button>`).join('');$('#word-bank').innerHTML=g.words.map(w=>`<button class="word ${g.level===2||g.level===3?'remember':''} ${g.selected.some(x=>x.id===w.id)?'selected':''}" ${g.level===2||g.selected.some(x=>x.id===w.id)?'disabled':''} ${g.level===3?`aria-label="Fire at ${esc(w.word)} bubble"`:''} data-word="${w.id}">${esc(w.word)}</button>`).join('');$('#instructions').textContent=g.level===2?'Words stay visible here • ← → move • Space jump • Fuse bombs slow you for 3 seconds':g.level===3?'Tap a moving bubble or its word above to fire • 20 seconds per sentence':'Select words in order • Click a filled slot to remove it';}
function selectWord(id){const g=game;if(!g||g.over||g.paused||g.lock||g.phase!=='play')return;const w=g.words.find(x=>x.id===id);if(!w||g.selected.some(x=>x.id===id))return;const slot=g.selected.length;g.selected.push(w);if(g.level===4&&g.answer[slot]===w.word){g.typed=.7;g.code=`accept token_${slot+1}();`;sound('good')}renderWords();if(g.selected.length===g.answer.length){const correct=g.selected.every((w,i)=>w.word===g.answer[i]);g.lock=correct?.75:.65;g.pendingStatus=correct?'correct':'wrong';feedback(correct?'Correct! '+(g.level===2||g.level===3?`Fresh ${levels[g.level].time} seconds.`:g.level===4?'+5 seconds.':'Monster pushed back.'):'Wrong order — resetting the words.');sound(correct?'good':'bad');if(correct){g.correct++;if(g.level===1)g.enemyX=Math.min(1050,g.enemyX+115);if(g.level===2||g.level===3)g.time=levels[g.level].time*1000;if(g.level===4)g.time+=5000;hud();}}}
