 for(const f of g.fallers){f.y+=f.speed*dt;const py=580-g.jump;if(Math.abs(f.x-g.playerX)<(f.bomb?48:60)&&f.y>py-105&&f.y<py+25){f.remove=true;if(f.bomb){g.slow=3;explosion(f.x,f.y);feedback('Boom! Slowed for 3 seconds.')}else selectWord(f.word.id);}else if(f.y>=590){f.remove=true;if(f.bomb)explosion(f.x,575,140)}}g.fallers=g.fallers.filter(f=>!f.remove);
